      r3fTechniques: ['Three scene panels with distinct geometries', 'Hand mesh geometry or simplified shapes', 'Sealed box geometry for isolation', 'Glowing thread line for dependent connection', 'Bloom and useSpring for animations'],
      camera: { position: [0, 3, 10], fov: 50, autoRotate: true },
